package crdt

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/reearth/ygo/encoding"
)

// Cross-language conformance for delete sets that cover items already deleted,
// against genuine yjs@13.6.x output. Fixtures are generated by
// testutil/gen_fixtures_redelete.js (`make fixtures`); each scenario below
// replays its steps exactly, with garbage collection off.

type redeleteFixture struct {
	Name  string `json:"name"`
	Steps []struct {
		Label   string   `json:"label"`
		Updates []string `json:"updates"`
	} `json:"steps"`
	State string `json:"state"`
	Text  string `json:"text"`
}

type redeleteCtx struct {
	text *YText
	um   *UndoManager
}

type redeleteStep struct {
	label string
	run   func(*testing.T, *Doc, redeleteCtx, func(*Doc, []byte, any) error)
}

// redeleteDeletedRun types s into "t" under an UndoManager, then deletes it all.
func redeleteDeletedRun(s string) func(*Doc) redeleteCtx {
	return func(doc *Doc) redeleteCtx {
		text := doc.GetText("t")
		um := NewUndoManager(doc, []SharedType{text})
		doc.Transact(func(txn *Transaction) { text.Insert(txn, 0, s, nil) })
		um.StopCapturing()
		doc.Transact(func(txn *Transaction) { text.Delete(txn, 0, text.Len()) })
		um.StopCapturing()
		return redeleteCtx{text: text, um: um}
	}
}

// redeleteApply applies a delete set of client 1's ranges, each a clock and a
// length, through apply.
func redeleteApply(label string, ranges ...[2]uint64) redeleteStep {
	return redeleteStep{label, func(t *testing.T, doc *Doc, _ redeleteCtx, apply func(*Doc, []byte, any) error) {
		ds := newDeleteSet()
		for _, r := range ranges {
			ds.add(ID{Client: 1, Clock: r[0]}, int(r[1]))
		}
		require.NoError(t, apply(doc, encodeStructStoreV1(nil, ds, nil, newStructStore()), "remote"))
	}}
}

func redeleteUndo(label string) redeleteStep {
	return redeleteStep{label, func(t *testing.T, _ *Doc, c redeleteCtx, _ func(*Doc, []byte, any) error) {
		require.True(t, c.um.Undo(), "undo")
	}}
}

func redeleteRedo(label string) redeleteStep {
	return redeleteStep{label, func(t *testing.T, _ *Doc, c redeleteCtx, _ func(*Doc, []byte, any) error) {
		require.True(t, c.um.Redo(), "redo")
	}}
}

var redeleteScenarios = map[string]struct {
	setup func(*Doc) redeleteCtx
	steps []redeleteStep
}{
	"redelete_redone_run": {
		redeleteDeletedRun("abcdefgh"),
		[]redeleteStep{redeleteUndo("undo"), redeleteApply("redelete", [2]uint64{2, 3}), redeleteRedo("redo"), redeleteUndo("undo again")},
	},
	"redelete_start_inside_supplementary": {
		redeleteDeletedRun("x😀y"),
		[]redeleteStep{redeleteApply("redelete", [2]uint64{2, 1}), redeleteUndo("undo"), redeleteRedo("redo")},
	},
	"redelete_end_inside_supplementary": {
		redeleteDeletedRun("x😀y"),
		[]redeleteStep{redeleteApply("redelete", [2]uint64{1, 1}), redeleteUndo("undo"), redeleteRedo("redo")},
	},
	"cascade_into_supplementary": {
		func(doc *Doc) redeleteCtx {
			arr := doc.GetArray("a")
			text := NewTextPrelim()
			doc.Transact(func(txn *Transaction) { arr.InsertType(txn, 0, text) })
			doc.Transact(func(txn *Transaction) { text.Insert(txn, 0, "x😀y", nil) })
			return redeleteCtx{text: text}
		},
		[]redeleteStep{redeleteApply("delete", [2]uint64{0, 3})},
	},
	"two_ranges": {
		func(doc *Doc) redeleteCtx {
			text := doc.GetText("t")
			doc.Transact(func(txn *Transaction) { text.Insert(txn, 0, "abcdefgh", nil) })
			doc.Transact(func(txn *Transaction) { text.Insert(txn, 8, "XYZ", nil) })
			doc.Transact(func(txn *Transaction) { text.Delete(txn, 8, 3) })
			return redeleteCtx{text: text}
		},
		[]redeleteStep{redeleteApply("delete", [2]uint64{2, 2}, [2]uint64{9, 1})},
	},
}

// splitUpdateV1 returns an update's structs section and its delete set, and
// requires the delete set to be written sorted and merged.
func splitUpdateV1(t *testing.T, u []byte) ([]byte, DeleteSet) {
	t.Helper()
	_, ds, err := decodeStructsV1(New(), u)
	require.NoError(t, err)
	tail := encoding.EncodeBytes(func(enc *encoding.Encoder) { encodeDeleteSet(enc, ds) })
	require.True(t, bytes.HasSuffix(u, tail), "delete set not written sorted and merged: %x", u)
	return u[:len(u)-len(tail)], ds
}

// requireCovered requires every range of sub to be deleted in super.
func requireCovered(t *testing.T, super, sub DeleteSet, msg string) {
	t.Helper()
	for client, ranges := range sub.clients {
		for _, r := range ranges {
			require.True(t, deleteSetCovers(super, client, r), "%s: %d:%v", msg, client, r)
		}
	}
}

// requireYjsUpdates requires got to carry the structs of want byte for byte,
// update by update, and exactly the deletions of want plus, at most, clocks
// already deleted before the step: ygo's OnUpdate may repeat those, and where
// Yjs emits nothing ygo may emit an update without structs.
func requireYjsUpdates(t *testing.T, label string, want []string, got [][]byte, before DeleteSet) {
	t.Helper()
	if len(want) == 0 {
		for _, g := range got {
			structs, ds := splitUpdateV1(t, g)
			require.Equal(t, []byte{0}, structs, "%s: Yjs emits no update, ygo emitted structs: %x", label, g)
			requireCovered(t, before, ds, label+": Yjs emits no update, ygo emitted a new deletion")
		}
		return
	}
	require.Len(t, got, len(want), "%s: updates emitted", label)
	for i, w := range want {
		wb, err := hex.DecodeString(w)
		require.NoError(t, err)
		wantStructs, wantDS := splitUpdateV1(t, wb)
		gotStructs, gotDS := splitUpdateV1(t, got[i])
		require.Equal(t, hex.EncodeToString(wantStructs), hex.EncodeToString(gotStructs), "%s: structs of update %d", label, i)
		requireCovered(t, gotDS, wantDS, fmt.Sprintf("%s: update %d lacks a deletion", label, i))
		allowed := newDeleteSet()
		allowed.Merge(wantDS)
		allowed.Merge(before)
		requireCovered(t, allowed, gotDS, fmt.Sprintf("%s: update %d carries a deletion Yjs does not", label, i))
	}
}

func applyUpdateV1AsV2(doc *Doc, u []byte, origin any) error {
	v2, err := UpdateV1ToV2(u)
	if err != nil {
		return err
	}
	return ApplyUpdateV2(doc, v2, origin)
}

func TestConformance_Redelete_MatchesYjs(t *testing.T) {
	t.Parallel()
	raw, err := os.ReadFile("testdata/redelete_yjs_fixtures.json")
	require.NoError(t, err, "run `make fixtures`")
	var file struct {
		Fixtures []redeleteFixture `json:"fixtures"`
	}
	require.NoError(t, json.Unmarshal(raw, &file))
	seen := map[string]bool{}
	for _, fx := range file.Fixtures {
		require.False(t, seen[fx.Name], "fixture %q appears twice", fx.Name)
		seen[fx.Name] = true
	}
	for name := range redeleteScenarios {
		require.True(t, seen[name], "no fixture for scenario %q", name)
	}
	for _, fx := range file.Fixtures {
		for _, v := range []struct {
			name  string
			apply func(*Doc, []byte, any) error
		}{{"v1", ApplyUpdateV1}, {"v2", applyUpdateV1AsV2}} {
			t.Run(fx.Name+"/"+v.name, func(t *testing.T) {
				t.Parallel()
				sc, ok := redeleteScenarios[fx.Name]
				require.True(t, ok, "no scenario for fixture %q", fx.Name)
				require.Len(t, sc.steps, len(fx.Steps))
				doc := New(WithClientID(1), WithGC(false))
				c := sc.setup(doc)
				if c.um != nil {
					defer c.um.Destroy()
				}
				// A replica that applies everything the doc emits after the
				// setup must end with Yjs's final state too.
				replica := New(WithClientID(2), WithGC(false))
				require.NoError(t, ApplyUpdateV1(replica, EncodeStateAsUpdateV1(doc, nil), nil))
				var emitted [][]byte
				doc.OnUpdate(func(u []byte, _ any) { emitted = append(emitted, bytes.Clone(u)) })
				for i, step := range fx.Steps {
					require.Equal(t, step.Label, sc.steps[i].label, "step %d", i)
					before := buildDeleteSet(doc.store)
					emitted = nil
					sc.steps[i].run(t, doc, c, v.apply)
					requireYjsUpdates(t, step.Label, step.Updates, emitted, before)
					for _, u := range emitted {
						require.NoError(t, ApplyUpdateV1(replica, u, nil))
					}
				}
				require.Equal(t, fx.State, hex.EncodeToString(EncodeStateAsUpdateV1(doc, nil)), "final state")
				require.Equal(t, fx.State, hex.EncodeToString(EncodeStateAsUpdateV1(replica, nil)), "final state of a replica of the emitted updates")
				require.Equal(t, fx.Text, c.text.ToString())
			})
		}
	}
}
